module KDEInferenceTest

using Test
using KernelSmoothing
using KernelSmoothing: PiecewisePolynomialKernel, _secondderivative
using Distributions: Normal, MixtureModel, pdf as npdf, quantile as nquantile
using Random: MersenneTwister

# reference values from nprobust 1.0.0, generated by data/kdrobust_golden.R
include(joinpath(@__DIR__, "data", "kdrobust_golden.jl"))

const X = round.([nquantile(Normal(), mod(i * 0.6180339887498949, 1)) + 0.3 * sin(i^2) for i in 1:500]; digits = 2)
const EVAL = [-1, -0.3, 0, 0.5, 1.2]
const NPKERNELS = Dict("epa" => EpanechnikovKernel(), "uni" => UniformKernel())

@testset "agrees with nprobust" begin
  for c in KDROBUST
    bw = c.h === nothing ? (c.bwselect == "imse-dpi" ? IMSEOptimal() : MSEOptimal()) : c.h
    m = fit(PointwiseDensity, X; points = EVAL, kernel = NPKERNELS[c.kernel], bandwidth = bw,
            pilot = c.b, compat = true)
    @test all(isapprox.(m.h, c.hused; rtol = 1e-12))
    @test all(isapprox.(m.b, c.bused; rtol = 1e-12))
    @test m.nwindow == c.N
    @test all(isapprox.(m.estimate, c.f_us; rtol = 1e-12))
    @test all(isapprox.(m.estimate_bc, c.f_bc; rtol = 1e-11))
    @test all(isapprox.(m.se, c.se_us; rtol = 1e-12))
    @test all(isapprox.(m.se_rbc, c.se_rb; rtol = 1e-11))
  end
  s = selectbandwidth(IMSEOptimal(), SmoothingData(X), EpanechnikovKernel(); compat = true)
  @test s.h ≈ KDBW_IMSE_DEFAULT_GRID.h rtol = 1e-12
  @test s.details.b ≈ KDBW_IMSE_DEFAULT_GRID.b rtol = 1e-12
end

@testset "the bias correction" begin
  # A fine grid weighted by the normal density: the estimates are its expectations,
  # so that estimate minus density is the bias (exact-expectation check of the survey).
  g = collect(-8:1e-4:8)
  d = SmoothingData(g; weights = npdf.(Normal(), g))
  m = fit(PointwiseDensity, d; points = [0.0], bandwidth = 0.2, minobs = 0)
  mc = fit(PointwiseDensity, d; points = [0.0], bandwidth = 0.2, minobs = 0, compat = true)
  f0 = npdf(Normal(), 0.0)
  @test m.estimate[1] - f0 ≈ -1.59e-3 rtol = 0.01        # conventional
  @test mc.estimate_bc[1] - f0 ≈ -7.08e-4 rtol = 0.01    # nprobust's constant: 5/9 of the bias removed
  @test abs(m.estimate_bc[1] - f0) < 1e-5                 # the constant of Calonico, Cattaneo and Farrell
  # with rho = 1 the bias-corrected estimate is a kernel estimate with a fourth-order kernel
  k = EpanechnikovKernel()
  c0, c2 = _secondderivative(k)
  M(u) = k(u) * (1 - moment(k, 2) / 2 * (c0 + c2 * u^2))
  @test sum(u^2 * M(u) * 1e-5 for u in -1:1e-5:1) ≈ 0 atol = 1e-8
  @test sum(u^4 * M(u) * 1e-5 for u in -1:1e-5:1) < 0
end

@testset "definition" begin
  w = 1.0 .+ mod.(1:500, 3)
  for k in (EpanechnikovKernel(), UniformKernel(), BiweightKernel(), GaussianKernel()), (h, b) in ((0.3, 0.3), (0.25, 0.5))
    m = fit(PointwiseDensity, X; weights = w, points = EVAL, kernel = k, bandwidth = h, pilot = b, minobs = 0)
    c0, c2 = _secondderivative(k)
    ρ, κ = h / b, moment(k, 2) / 2
    for (j, x0) in enumerate(EVAL)
      u = (x0 .- X) ./ h
      g = k.(u) ./ h
      mm = (k.(u) .- ρ^3 * κ .* k.(ρ .* u) .* (c0 .+ c2 .* (ρ .* u) .^ 2)) ./ h
      f, fbc = sum(w .* g) / sum(w), sum(w .* mm) / sum(w)
      @test m.estimate[j] ≈ f rtol = 1e-12
      @test m.estimate_bc[j] ≈ fbc rtol = 1e-12
      @test m.se[j] ≈ sqrt(sum(w .^ 2 .* (g .- f) .^ 2)) / sum(w) rtol = 1e-10
      @test m.se_rbc[j] ≈ sqrt(sum(w .^ 2 .* (mm .- fbc) .^ 2)) / sum(w) rtol = 1e-10
    end
  end
end

@testset "interface" begin
  d = SmoothingData(X)
  m = fit(PointwiseDensity, d)
  @test length(m.points) == 30 && m.points[1] ≈ nquantile(X, 0.1)
  @test m.selection.rule == IMSEOptimal()
  @test fit(PointwiseDensity, d; points = [0.0]).selection.rule == MSEOptimal()
  @test fit(PointwiseDensity, d; points = [0.0], kernel = BiweightKernel()).selection.rule == MSEOptimal()
  ms = fit(PointwiseDensity, d; points = EVAL, bandwidth = MSEOptimal(), pilot = :selected)
  @test ms.b == ms.selection.details.b   # the pilot bandwidths are already floored
  c = confint(m)
  @test all(c[:, 1] .< m.estimate_bc .< c[:, 2])
  @test confint(m; method = Conventional(), level = 0.9) ≈
        hcat(m.estimate .- 1.6448536269514722 .* m.se, m.estimate .+ 1.6448536269514722 .* m.se)
  t = coeftable(m)
  @test t.estimate_bc == m.estimate_bc && t.upper_rbc == c[:, 2] && length(t.point) == 30
  @test coef(m) == m.estimate && stderror(m; method = RobustBiasCorrected()) == m.se_rbc
  @test nobs(m) == 500 && bandwidth(m) == m.h
  @test occursin("robust bias-corrected", sprint(show, MIME("text/plain"), m))
  @test occursin("IMSEOptimal(), pilots anchored on Sheather–Jones", sprint(show, MIME("text/plain"), fit(PointwiseDensity, X)))
  @test occursin("PointwiseDensity", sprint(show, m))
  # intervals for a density estimate with its own bandwidth
  f = fit(KDE, X; bandwidth = 0.3)
  mf = fit(PointwiseDensity, d; points = EVAL, bandwidth = 0.3, minobs = 0)
  @test confint(f, EVAL) == confint(mf)
  @test confint(f, EVAL; method = Conventional()) ≈
        hcat(pdf.(f, EVAL) .- 1.959963984540054 .* stderror.(f, EVAL), pdf.(f, EVAL) .+ 1.959963984540054 .* stderror.(f, EVAL))
  # the integrated plug-in bandwidth as the bandwidth of a density estimate
  @test bandwidth(fit(KDE, X; bandwidth = IMSEOptimal())) ≈
        selectbandwidth(IMSEOptimal(), d, EpanechnikovKernel()).h
  # coverage-error rescaling leaves second-order density bandwidths unchanged, as in nprobust
  @test selectbandwidth(CoverageOptimal(), d, EpanechnikovKernel(); points = EVAL).h ==
        selectbandwidth(MSEOptimal(), d, EpanechnikovKernel(); points = EVAL).h
end

@testset "plug-in bandwidths for densities" begin
  # a bimodal density: nprobust's normal-reference pilot for f'' is far too wide, so
  # its bandwidth explodes in the valley; the default adapts through Sheather–Jones
  dist = MixtureModel([Normal(-1, 0.5), Normal(1, 0.5)])
  x = rand(MersenneTwister(11), dist, 2000)
  d = SmoothingData(x)
  k = EpanechnikovKernel()
  s = selectbandwidth(MSEOptimal(), d, k; points = [-1.0, 0.0, 1.0])
  sc = selectbandwidth(MSEOptimal(), d, k; points = [-1.0, 0.0, 1.0], compat = true)
  hsj = bandwidth(SheatherJones(), d, k)
  @test s.details.sheatherjones == hsj
  @test all(s.h .< 2hsj) && sc.h[2] > 5hsj
  @test s.details.b[1] < sc.details.b[1] / 2
  # the integrated bandwidth is close to Sheather–Jones
  @test selectbandwidth(IMSEOptimal(), d, k).h ≈ hsj rtol = 0.2
  # regularization keeps the bandwidth finite where f'' vanishes (the inflection
  # points ±1 of the normal density)
  z = rand(MersenneTwister(12), Normal(), 2000)
  dz = SmoothingData(z)
  r1 = selectbandwidth(MSEOptimal(), dz, k; points = [1.0])
  r0 = selectbandwidth(MSEOptimal(regularization = 0), dz, k; points = [1.0])
  @test r1.h[1] < r0.h[1]
  # equivariance under location and scale
  s2 = selectbandwidth(MSEOptimal(), SmoothingData(3 .+ 2 .* x), k; points = [1.0, 3.0, 5.0])
  @test s2.h ≈ 2 .* s.h rtol = 1e-6
  # any symmetric second-order kernel, and the default of the fit
  for kk in (BiweightKernel(), GaussianKernel())
    @test all(isfinite, selectbandwidth(MSEOptimal(), d, kk; points = [0.0, 1.0]).h)
    @test fit(PointwiseDensity, d; points = [0.0], kernel = kk).selection.rule == MSEOptimal()
  end
  # nprobust's kdrobust accepts the Epanechnikov and uniform kernels only
  @test_throws ArgumentError fit(PointwiseDensity, d; points = [0.0], kernel = BiweightKernel(), compat = true)
  @test_throws ArgumentError fit(PointwiseDensity, d; points = [0.0], kernel = BiweightKernel(), bandwidth = 0.5,
                                 compat = true)
  @test fit(PointwiseDensity, d; points = [0.0], kernel = UniformKernel(), compat = true).selection.rule == MSEOptimal()
  @test_throws ArgumentError selectbandwidth(MSEOptimal(), d, BiweightKernel(); points = [0.0], compat = true)
end

@testset "plug-in bandwidths where the density vanishes, and responses" begin
  k = EpanechnikovKernel()
  v = quantile.(Normal(), range(0.002, 0.998; length = 500))
  c = [v; 10 .+ v]   # two clusters, with nothing near 5
  d = SmoothingData(c)
  s = selectbandwidth(MSEOptimal(), d, k; points = [0.0, 5.0, 10.0])
  @test all(isfinite, s.h) && s.h[2] == knn_distance(d, 5.0, 21)
  s0 = selectbandwidth(MSEOptimal(), d, k; points = [5.0], minobs = 0)
  @test s0.h[1] == 5 - minimum(c)   # the cap: the distance to the farther end
  @test isfinite(fit(PointwiseDensity, c; points = [5.0]).estimate[1])
  # the density rules ignore responses, also through prepared data
  dy = SmoothingData(c, sin.(c))
  @test fit(PointwiseDensity, dy; points = [0.0, 1.0]).h == fit(PointwiseDensity, d; points = [0.0, 1.0]).h
  @test bandwidth(fit(KDE, dy; bandwidth = IMSEOptimal())) == bandwidth(fit(KDE, d; bandwidth = IMSEOptimal()))
end

@testset "arguments" begin
  d = SmoothingData(X)
  asym = PiecewisePolynomialKernel([-1.0, 0.0, 2.0], [[2/3, 2/3], [2/3, -1/3]])
  @test_throws ArgumentError fit(PointwiseDensity, d; kernel = asym, bandwidth = 0.3)
  @test_throws ArgumentError fit(PointwiseDensity, d; kernel = derivative(BiweightKernel()), bandwidth = 0.3)
  @test_throws ArgumentError fit(PointwiseDensity, d; bandwidth = RuleOfThumb())
  @test_throws ArgumentError fit(PointwiseDensity, d; bandwidth = MSEOptimal(), kernel = GaussianKernel(), compat = true)
  @test_throws ArgumentError fit(PointwiseDensity, d; bandwidth = 0.3, rho = 0)
  @test_throws ArgumentError fit(PointwiseDensity, d; bandwidth = 0.3, pilot = :selected)
  @test_throws ArgumentError fit(PointwiseDensity, d; bandwidth = "wide")
  @test_throws ArgumentError fit(PointwiseDensity, d; bandwidth = 0.3, minobs = -1)
  @test_throws ArgumentError fit(PointwiseDensity, d; bandwidth = MSEOptimal(interior = true))
  @test_throws ArgumentError confint(fit(PointwiseDensity, d; bandwidth = 0.3); level = 2)
end

@testset "the window holds every observation that a kernel weights" begin
  # Gridded data, the uniform kernel and b > h: at the edge of the window ρu rounds
  # to -1, where the kernel is 1/2, for 146 observations that a window of
  # (xᵢ - x₀)/b left out
  x = round.([nquantile(Normal(), mod(i * 0.7548776662466927, 1)) for i in 1:3000]; digits = 1)
  k = UniformKernel()
  c0, c2 = _secondderivative(k)
  for compat in (true, false)
    m = fit(PointwiseDensity, x; points = [0.7], kernel = k, bandwidth = 0.4, pilot = 0.9, compat)
    κ = compat ? (c0 * moment(k, 4) + c2 * moment(k, 6)) / 24 : moment(k, 2) / 2
    ρ = 0.4 / 0.9
    bf = sum(begin
               u = (0.7 - xi) / 0.4
               k(u) - ρ^3 * κ * k(ρ * u) * (c0 + c2 * (ρ * u)^2)
             end for xi in x) / (0.4 * 3000)
    @test only(m.estimate_bc) ≈ bf rtol = 1e-13
    @test vcov(m; method = RobustBiasCorrected())[1, 1] ≈ only(m.se_rbc)^2 rtol = 1e-12
  end
end

@testset "argument checks of density fits" begin
  m = fit(PointwiseDensity, X; points = [-1.0, 0.0])
  @test_throws "regression" stderror(m; method = Honest(1.0))
  @test_throws "regression" vcov(m; method = Honest(1.0))
  ml = fit(LocalPolynomialDensity, X; points = [-1.0, 0.0])
  @test_throws "regression" stderror(ml; method = Honest(1.0))
  @test_throws "regression" vcov(ml; method = Honest(1.0))
  @test_throws ArgumentError fit(PointwiseDensity, X; points = [0.0], bandwidth = 0.3, rho = Inf, minobs = 0)
  # the density rules need kernels that integrate to one
  dx = SmoothingData(X)
  g = derivative(GaussianKernel(), 2)
  for rule in (NormalReference(), SilvermanRule(), SheatherJones(), LSCV())
    @test_throws "integrate to one" selectbandwidth(rule, dx, g)
  end
  # a KDE takes nothing for its default bandwidth, and gives an interval at a point
  f = fit(KDE, X)
  @test bandwidth(fit(KDE, X; bandwidth = nothing)) == bandwidth(f)
  @test confint(f, 0.3) == Tuple(confint(f, [0.3]))
  @inferred vcov(ml)
  @inferred confband(ml)
end

@testset "windows without data, intervals at zero, counts" begin
  xe = -log.(1 .- mod.((1:500) .* 0.7548776662466927, 1))
  m = fit(PointwiseDensity, xe; points = [4.0, 30.0], bandwidth = 0.3, minobs = 0)
  mc = fit(PointwiseDensity, xe; points = [4.0, 30.0], bandwidth = 0.3, minobs = 0, compat = true)
  # no observation has positive weight at 30: no standard error, rather than zero
  @test m.estimate[2] == 0 && isnan(m.se[2]) && isnan(m.se_rbc[2]) && mc.se[2] == 0
  @test all(isnan, confint(m)[2, :]) && confint(mc)[2, :] == [0.0, 0.0]
  @test all(isnan, vcov(m)[2, :]) && isfinite(vcov(m)[1, 1])
  b = confband(m; rng = MersenneTwister(1))
  @test isnan(b.lower[2]) && isfinite(b.lower[1])
  # the lower ends are clamped at zero, unless compat
  @test confint(m)[1, 1] == 0 && confint(mc)[1, 1] < 0
  f = fit(KDE, xe; bandwidth = 0.3)
  @test confint(f, 5.0)[1] == 0 && all(isnan, confint(f, 30.0))
  # counts: positive weight in the larger window, or all within max(h, b) under compat
  xt = repeat(collect(0.0:0.1:2.0), 10)
  @test fit(PointwiseDensity, xt; points = [1.0], bandwidth = 0.5, minobs = 0).nwindow == [90]
  @test fit(PointwiseDensity, xt; points = [1.0], bandwidth = 0.5, minobs = 0, compat = true).nwindow == [110]
  # grid = :points needs the evaluation points
  @test_throws ArgumentError selectbandwidth(IMSEOptimal(grid = :points), SmoothingData(xe), EpanechnikovKernel())
  @test IMSEOptimal().grid === nothing
end

end
